extend schema @link(url: "https://specs.apollo.dev/federation/v2.0", import: ["@key"])

interface Product @key(fields: "id") {
  id: ID!
  name: String!
}

type Book implements Product {
  id: ID!
  name: String!
  author: String!
}

type Movie implements Product {
  id: ID!
  name: String!
  director: String!
}

type Query {
    movie(id: ID!): Movie
}

extend schema @link(url: "https://specs.apollo.dev/federation/v2.6", import: [
  "@key",
  "@override"
])

type Product @key(fields: "id") {
    id: ID!
    name: String! @override(from: "old-product-service", label: "percent(5)")
}

type Query {
    product(id: ID!): Product
}

extend schema @link(url: "https://specs.apollo.dev/federation/v2.1", import: ["@key", "@shareable"])

type Product @key(fields: "id") {
  id: ID!
  name: String!
  position: Position
}

type Position @shareable {
  x: Float!
  y: Float!
}

extend type Position @shareable {
